from collections import Counter
def f(g):
    n=len(g)
    def orb(r,c):
        return {(r,c),(c,r),(n-1-r,c),(c,n-1-r),(r,n-1-c),(n-1-c,r),(n-1-r,n-1-c),(n-1-c,n-1-r)}
    out=[[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            vals=[g[i][j] for i,j in orb(r,c)]
            non2=[v for v in vals if v!=2]
            out[r][c]=Counter(non2).most_common(1)[0][0] if non2 else 2
    return out
